WITH ranked AS (SELECT * FROM payments QUALIFY ROW_NUMBER() OVER (PARTITION BY method ORDER BY paid_at DESC, id) = 1), with_windows AS (SELECT *, AVG(amount) OVER w_part AS last3_avg_amount, MIN(amount) OVER w_part AS last3_min_amount, MAX(amount) OVER w_part AS last3_max_amount FROM ranked WHERE order_id = 30 WINDOW w_part AS (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)), with_windows_payments AS (SELECT *, AVG(last3_max_amount) OVER (PARTITION BY YEAR(paid_at), status) AS paid_at_year_avg_last3_max_amount, ROUND(last3_max_amount / SUM(last3_max_amount) OVER (PARTITION BY order_id), 4) AS last3_max_amount_share, AVG(last3_avg_amount) OVER (ORDER BY last3_max_amount, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS last3_avg_amount_avg_2_prior, PERCENT_RANK() OVER w_part AS last3_min_amount_percent_rank FROM with_windows WINDOW w_part AS (PARTITION BY order_id ORDER BY last3_min_amount DESC NULLS LAST)), enriched AS (SELECT id, order_id, method, amount, status, last3_avg_amount, last3_max_amount, last3_max_amount_share, last3_avg_amount_avg_2_prior, SUM(last3_max_amount) OVER (ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_last3_max_amount, RANK() OVER (PARTITION BY MONTH(paid_at), status ORDER BY amount DESC NULLS LAST) AS amount_rank FROM with_windows_payments) SELECT d.channel, d.status AS order_status, a.status AS payment_status, COUNT(*) AS num_rows, ROUND(SUM(a.cumulative_last3_max_amount), 2) AS total_cumulative_last3_max_amount, ROUND(SUM(a.amount_rank), 2) AS total_amount_rank, GROUPING_ID() AS level_id FROM enriched a LEFT JOIN orders d ON a.order_id = d.id GROUP BY ROLLUP (d.channel, d.status, a.status) ORDER BY num_rows NULLS FIRST;
